INSERT INTO public.flash_memories VALUES ('353714d9-450a-4b41-9750-852ce692b060', 'Python best practice — fibonacci iterativo con type hints:
```python
def fibonacci(n: int) -> int:
    """Retorna el n-ésimo número de Fibonacci. Raise ValueError si n < 0."""
    if n < 0:
        raise ValueError("n debe ser >= 0")
    a, b = 0, 1
    for _ in range(n):
        a, b = b, a + b
    return a
```
