INSERT INTO public.flash_memories VALUES ('93450678-1246-4c48-a876-c89ce4425a6a', 'Python best practice — truncar texto con ellipsis:
```python
def truncar(texto: str, max_len: int = 80) -> str:
    """Trunca texto a max_len caracteres, agregando ''...'' si es necesario."""
    if len(texto) <= max_len:
        return texto
    return texto[:max_len - 3] + "..."
```
