INSERT INTO public.flash_memories VALUES ('91c833f5-d2c5-4b83-be8a-e3a6716ac922', 'Python best practice — interpolación lineal:
```python
def lerp(a: float, b: float, t: float) -> float:
    """Interpolación lineal entre a y b. t=0 retorna a, t=1 retorna b."""
    return a + (b - a) * t
```
