INSERT INTO public.flash_memories VALUES ('8728bc35-98f1-4991-af5f-efaa75867dfe', 'Python best practice — cesar cipher:
```python
def cifrar_cesar(texto: str, desplazamiento: int = 3) -> str:
    """Cifrado César: desplaza cada letra por n posiciones."""
    resultado = []
    for c in texto:
        if c.isalpha():
            base = ord(''A'') if c.isupper() else ord(''a'')
            resultado.append(chr((ord(c) - base + desplazamiento) % 26 + base))
        else:
            resultado.append(c)
    return "".join(resultado)
```
