INSERT INTO public.flash_memories VALUES ('d1753b5b-4fa8-4d12-bccd-ba699f285ba7', 'Python regla de estilo: funciones simples = docstring de 1 línea.
```python
# ✅ Bien:
def sumar(a: float, b: float) -> float:
    """Suma dos números."""
    return a + b

# ❌ Mal:
def sumar(a: int, b: int) -> int:
    """
    Suma dos números enteros y devuelve el resultado.
    
    :param a: El primer número entero.
    :type a: int
    :param b: El segundo número entero.
    :type b: int
    :return: La suma de los dos números.
    :rtype: int
    """
    return a + b
```
