INSERT INTO public.flash_memories VALUES ('5c59bea3-19d7-44bf-bee0-5f901271caf5', 'Python best practice — tamaño de archivo legible:
```python
def tamaño_legible(bytes: int) -> str:
    """Convierte bytes a formato legible: 1536 -> ''1.5 KB''."""
    for unidad in ("B", "KB", "MB", "GB", "TB"):
        if bytes < 1024:
            return f"{bytes:.1f} {unidad}"
        bytes /= 1024
    return f"{bytes:.1f} PB"
```
