INSERT INTO public.flash_memories VALUES ('53caa27d-92d6-4626-a146-ea62d10dc040', 'Python best practice — safe division:
```python
def dividir(a: float, b: float) -> float | None:
    """División segura. Retorna None si b es 0."""
    if b == 0:
        return None
    return a / b
```
