INSERT INTO public.flash_memories VALUES ('424db50d-598c-4b05-a9b3-5a0e85b27b1f', 'Python best practice — result type (sin excepciones):
```python
from dataclasses import dataclass
from typing import Generic, TypeVar

T = TypeVar("T")

@dataclass
class Result(Generic[T]):
    """Encapsula éxito o error sin usar excepciones."""
    ok: bool
    value: T | None = None
    error: str | None = None

    @staticmethod
    def success(value: T) -> "Result[T]":
        return Result(ok=True, value=value)

    @staticmethod
    def failure(error: str) -> "Result[T]":
        return Result(ok=False, error=error)
```
