INSERT INTO public.flash_memories VALUES ('b5fcaeab-be27-4b8a-88c8-0a8f8aaa563e', 'Python regla de estilo: usar float para ''números'' genéricos.
```python
# ✅ Bien — acepta int y float:
def calcular(valor: float) -> float: ...

# ❌ Mal — rechaza floats:
def calcular(valor: int) -> int: ...
```
